+	}
+	if len(checkpointInfo.SubSteps) != 1 {
+		t.Fatalf("checkpointInfo should have 1 sub-step, got %d", len(checkpointInfo.SubSteps))
+	}
+
+	readSession := checkpointInfo.SubSteps[0]
