+func appendChildStepAttrs(attrs []any, parent *Span, parentKey string) []any {
+	if parent == nil {
+		return attrs
+	}
+
+	seen := make(map[string]int, len(parent.children))
+	loopIndex := 0
+	for _, child := range parent.children {
+		if !child.ended {
+			child.End()
+		}
