+		key := fmt.Sprintf("steps.%s_ms", stepKey)
+		attrs = append(attrs, slog.Int64(key, child.duration.Milliseconds()))
+		if child.err != nil {
+			errKey := fmt.Sprintf("steps.%s_err", stepKey)
+			attrs = append(attrs, slog.Bool(errKey, true))
+		}
