37	// parseTraceEntry parses a JSON log line into a traceEntry.
38	// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
39	func parseTraceEntry(line string) *traceEntry {
40		// Cheap pre-filter: skip full JSON parse for lines that can't be perf entries.
41		// Most lines in the shared log file are non-perf, so this avoids the
42		// marshalling cost for the common reject path.
43		if !strings.Contains(line, `"msg":"perf"`) {
44			return nil
45		}
46	
47		var raw map[string]json.RawMessage
48		if err := json.Unmarshal([]byte(line), &raw); err != nil {
49			return nil
50		}
51	
52		// Verify msg == "perf" after full parse (the pre-filter could match substrings)
53		var msg string
54		if msgRaw, ok := raw["msg"]; !ok {
55			return nil
56		} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
57			return nil
58		}
59	
60		entry := &traceEntry{}
