63		// zero values rather than discarding the entire entry.
64		if opRaw, ok := raw["op"]; ok {
65			_ = json.Unmarshal(opRaw, &entry.Op) //nolint:errcheck // best-effort
66		}
67		if dRaw, ok := raw["duration_ms"]; ok {
68			_ = json.Unmarshal(dRaw, &entry.DurationMs) //nolint:errcheck // best-effort
69		}
70		if errRaw, ok := raw["error"]; ok {
71			_ = json.Unmarshal(errRaw, &entry.Error) //nolint:errcheck // best-effort
72		}
