89			if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
90				name := strings.TrimPrefix(key, "steps.")
91				name = strings.TrimSuffix(name, "_ms")
92	
93				var ms int64
94				if err := json.Unmarshal(val, &ms); err == nil {
95					stepDurations[name] = ms
96				}
97			} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
98				name := strings.TrimPrefix(key, "steps.")
99				name = strings.TrimSuffix(name, "_err")
100	
101				var errFlag bool
102				if err := json.Unmarshal(val, &errFlag); err == nil {
103					stepErrors[name] = errFlag
104				}
105			}
106		}
107	
108		entry.Steps = buildTraceSteps(stepDurations, stepErrors)
109	
110		return entry
111	}
112	
113	type traceStepNode struct {
114		step     traceStep
115		children []*traceStepNode
116	}
117	
118	func buildTraceSteps(stepDurations map[string]int64, stepErrors map[string]bool) []traceStep {
119		nodes := make(map[string]*traceStepNode, len(stepDurations))
120		for name, ms := range stepDurations {
121			nodes[name] = &traceStepNode{
122				step: traceStep{
123					Name:       name,
124					DurationMs: ms,
125					Error:      stepErrors[name],
126				},
127			}
128		}
129	
130		roots := make([]*traceStepNode, 0, len(nodes))
131		for name, node := range nodes {
132			parentName, ok := traceStepParent(name, stepDurations)
133			if !ok {
134				roots = append(roots, node)
135				continue
136			}
137			nodes[parentName].children = append(nodes[parentName].children, node)
138		}
139	
140		return traceStepNodesToSteps(roots, "")
141	}
142	
143	func traceStepParent(name string, allSteps map[string]int64) (string, bool) {
144		for lastDot := strings.LastIndex(name, "."); lastDot >= 0; {
145			parent := name[:lastDot]
146			if _, exists := allSteps[parent]; exists {
147				return parent, true
148			}
149			lastDot = strings.LastIndex(parent, ".")
150		}
151		return "", false
152	}
153	
154	func traceStepNodesToSteps(nodes []*traceStepNode, parentName string) []traceStep {
155		sortTraceStepNodes(nodes, parentName)
156	
157		steps := make([]traceStep, 0, len(nodes))
158		for _, node := range nodes {
159			step := node.step
160			step.SubSteps = traceStepNodesToSteps(node.children, step.Name)
161			steps = append(steps, step)
162		}
163		return steps
164	}
165	
166	func sortTraceStepNodes(nodes []*traceStepNode, parentName string) {
167		slices.SortFunc(nodes, func(a, b *traceStepNode) int {
168			if parentName == "" {
169				return cmp.Compare(a.step.Name, b.step.Name)
170			}
171	
172			aIdx, aNumeric := traceStepChildIndex(parentName, a.step.Name)
173			bIdx, bNumeric := traceStepChildIndex(parentName, b.step.Name)
174			if aNumeric && bNumeric {
175				return cmp.Compare(aIdx, bIdx)
176			}
177			if aNumeric {
178				return -1
179			}
180			if bNumeric {
181				return 1
182			}
183			return cmp.Compare(a.step.Name, b.step.Name)
184		})
185	}
186	
187	func traceStepChildIndex(parentName, childName string) (int, bool) {
188		prefix := parentName + "."
189		if !strings.HasPrefix(childName, prefix) {
190			return 0, false
191		}
192		suffix := strings.TrimPrefix(childName, prefix)
193		idx, err := strconv.Atoi(suffix)
194		if err != nil || idx < 0 {
195			return 0, false
196		}
197		return idx, true
198	}
199	
200	// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
201	// ordered newest first. If hookFilter is non-empty, only entries with a matching
202	// Op field are included.
203	func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
204		f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
205		if err != nil {
206			if errors.Is(err, os.ErrNotExist) {
207				return nil, nil
208			}
209			return nil, fmt.Errorf("opening log file: %w", err)
210		}
211		defer f.Close()
212	
213		var entries []traceEntry
214	
215		scanner := bufio.NewScanner(f)
216		scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
217		for scanner.Scan() {
218			entry := parseTraceEntry(scanner.Text())
219			if entry == nil {
220				continue
221			}
222			if hookFilter != "" && entry.Op != hookFilter {
223				continue
224			}
225			entries = append(entries, *entry)
226		}
227	
228		if err := scanner.Err(); err != nil {
229			return nil, fmt.Errorf("reading log file: %w", err)
230		}
231	
232		// Take the last N entries
233		if len(entries) > last {
234			entries = entries[len(entries)-last:]
235		}
236	
237		// Reverse so newest entries are first
238		slices.Reverse(entries)
239	
240		return entries, nil
241	}
242	
243	// renderTraceEntries writes a formatted table of trace entries to w.
244	// If entries is empty, it prints a help message about enabling traces.
245	func renderTraceEntries(w io.Writer, entries []traceEntry) {
246		if len(entries) == 0 {
247			fmt.Fprintln(w, "No trace entries found.")
248			fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
249			fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
250			return
251		}
252	
253		for i, entry := range entries {
254			if i > 0 {
255				fmt.Fprintln(w)
256			}
257	
258			// Header line: op  duration  [timestamp]
259			header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
260			if !entry.Time.IsZero() {
261				header += "  " + entry.Time.Format(time.RFC3339)
262			}
263			fmt.Fprintln(w, header)
264			fmt.Fprintln(w)
265	
266			if len(entry.Steps) == 0 {
267				continue
268			}
269	
270			nameWidth := traceStepNameWidth(entry.Steps)
271	
272			// Column header
273			renderTraceTableRow(w, nameWidth, "STEP", "DURATION", false)
274	
275			// Step rows
276			for _, s := range entry.Steps {
277				dur := fmt.Sprintf("%dms", s.DurationMs)
278				renderTraceTableRow(w, nameWidth, s.Name, dur, s.Error)
279				renderTraceStepChildren(w, s.SubSteps, nameWidth, "  ")
280			}
281		}
282	}
