284	func traceStepNameWidth(steps []traceStep) int {
285		width := displayWidth("STEP")
286		for _, step := range steps {
287			width = max(width, displayWidth(step.Name))
288			width = max(width, traceStepChildrenNameWidth(step.SubSteps, "  "))
289		}
290		return width
