295		for i, step := range steps {
296			connector := traceStepConnector(i, len(steps))
297			label := prefix + connector + " " + step.Name
298			width = max(width, displayWidth(label))
299			width = max(width, traceStepChildrenNameWidth(step.SubSteps, traceStepChildPrefix(prefix, i, len(steps))))
300		}
301		return width
302	}
303	
304	func renderTraceStepChildren(w io.Writer, steps []traceStep, nameWidth int, prefix string) {
305		for i, step := range steps {
306			connector := traceStepConnector(i, len(steps))
307			label := prefix + connector + " " + step.Name
308			dur := fmt.Sprintf("%dms", step.DurationMs)
309			renderTraceTableRow(w, nameWidth, label, dur, step.Error)
310			renderTraceStepChildren(w, step.SubSteps, nameWidth, traceStepChildPrefix(prefix, i, len(steps)))
311		}
312	}
